with with_last as (select s.*, x.account_type, x.account_balance from customers s join lateral (select c.account_type, c.balance as account_balance from accounts c where c.customer_id = s.id order by c.opened_date desc, c.id desc limit 1) x on true) select id, name, email, segment, is_active, credit_limit, age, account_type, account_balance from with_last order by account_balance desc nulls first
